identity=dict(created=datetime.datetime.now().astimezone().isoformat(),dll=sha(A/'dinput8.dll'),probe=sha(A/'d2_runtime_probe.exe'),setup=sha(A/'d2coop_setup.exe'),previous=P.name,protocol=81,npcAttackPacketVersion=previous['npcAttackPacketVersion'],bankVersion=75,clips=382,banks=banks,nativeTables=previous['nativeTables'],runtimeVerified=False,coinProtocol=previous['coinProtocol'],coinCatalogListProtocol=previous['coinCatalogListProtocol'],scope='1214jg (protocol 81, pose version 13, Doppelganger world packet v6, shade kill packet v1, prop rest packet v1, door packet v1 with the Unlock kind, #186): 1214jf with pickup rewards from any of the local player own mode state slots confirmable (LootObject 47, a Far Reach pull with fromGrapple, a theft). Before, the observer refused every Far Reach reward, and a refused reward stopped the whole shared pickup sync (confirmed static; a pickpocket re-armed the catalog in mission-pickup-families-v1850a). An unconfirmed reward is now refused for that item only; coin-hook.json keeps the last refused or Far Reach reward checks, state id and vtable.')
(A/'identity.json').write_text(json.dumps(identity,indent=2))
